import{_ as o,o as d,c as a,a2 as t}from"./chunks/framework.Bum8orMG.js";const g=JSON.parse('{"title":"Changelog","description":"Release history for KatanaKit JS.","frontmatter":{"title":"Changelog","description":"Release history for KatanaKit JS."},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":null}'),s={name:"changelog.md"};function c(r,e,i,n,l,u){return d(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to this project are documented in this file.</p><h2 id="unreleased" tabindex="-1">[Unreleased] <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;[Unreleased]&quot;">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Katana UI foundations (<code>@katanakit/ui</code>, private workspace)</strong> — framework-agnostic <code>useButton</code>/<code>useButtonClass</code>, <code>useInput</code>, <code>useCard</code>, <code>useBadge</code> and <code>useAlert</code> (variants, sizes, loading state, accessible label/help/error wiring and dismissal) styled with <code>katanakit-css</code> tokens and <code>data-theme</code> dark mode. The package ships a self-contained <code>@katanakit/ui/styles.css</code> build, VitePress pages with live demos under UI Kit → Components, and jsdom tests. Not published to npm yet.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Docs site migrated to VitePress</strong> — sources live in <code>docs/</code> and are served at <code>docs.senseikatana.com/*</code> (old <code>/docs/*</code> links redirect via <code>_redirects</code>). The API reference is TypeDoc-generated (<code>docs/api/</code> + sidebar JSON) and the changelog page is materialized from <code>CHANGELOG.md</code> by <code>scripts/docs-prepare.mjs</code>, which skips TypeDoc when <code>src/</code> is unchanged. Pages keep YAML frontmatter (<code>title</code>, <code>description</code>) so Obsidian reads them as properties; JS/TS is embedded with <code>&lt;script setup lang=&quot;ts&quot;&gt;</code> (Vue-in-Markdown — VitePress has no MDX).</li><li><strong>Repository cleanup</strong> — removed the <code>playground/</code> workspace, the intermediate MkDocs tooling (<code>mkdocs.yml</code>, <code>hooks/</code>, Python) and the stale <code>content/</code> tree; the repo now has a single docs site and no extra workspaces. Deploy, CI, <code>setup-cloudflare.mjs</code> and docs were updated accordingly; the manual <code>bun run docs:gh</code> command keeps an Action-free gh-pages preview.</li></ul><h2 id="_5-1-1-2026-09-26" tabindex="-1">[5.1.1] - 2026-09-26 <a class="header-anchor" href="#_5-1-1-2026-09-26" aria-label="Permalink to &quot;[5.1.1] - 2026-09-26&quot;">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Filesystem service (Node/Bun)</strong> (<code>useReadFile</code>, <code>useReadFileBuffer</code>, <code>useWriteFile</code>, <code>useAppendFile</code>, <code>useReadJsonFile</code>, <code>useWriteJsonFile</code>, <code>useReadDir</code>, <code>useEnsureDir</code>, <code>useFileExists</code>, <code>useGetFileStats</code>, <code>useCopyFile</code>, <code>useMoveFile</code>, <code>useRemoveFile</code>, <code>useRemoveDir</code>) plus path helpers (<code>useGetDirname</code>, <code>useResolvePath</code>, <code>useJoinPath</code>, <code>useGetRelativePath</code>, <code>useGetBasename</code>, <code>useGetFileExtension</code>, <code>useGetCwd</code>, <code>useIsNode</code>) and module-relative readers (<code>useReadModuleFile</code>, <code>useReadModuleJson</code>, the <code>__dirname</code> pattern without <code>__dirname</code>). <code>node:fs/promises</code>/<code>node:path</code> load through dynamic <code>import()</code>, every fallible call returns a Safe Result with the native errno <code>code</code> (<code>ENOENT</code>, <code>EACCES</code>, …), and browsers/Workers get <code>ERR_FS_UNAVAILABLE</code> instead of a crash. <code>useReadJsonFile</code>/<code>useReadModuleJson</code> accept an optional Zod schema for boundary validation.</li><li><strong>Faker service</strong> (<code>useFakeUuid</code>, <code>useFakeEmail</code>, <code>useFakeFullName</code>, <code>useFakeFirstName</code>, <code>useFakeLastName</code>, <code>useFakePhone</code>, <code>useFakeCompanyName</code>, <code>useFakeUrl</code>, <code>useFakeText</code>, <code>useFakeNumber</code>, <code>useFakeBoolean</code>, <code>useFakeDate</code>, <code>useFakeVehicle</code>, <code>useFakeList</code>, <code>useFakeSeed</code>, <code>useFakeSetDefaultRefDate</code>) — generic fake data for tests, seeds and forms. <code>useFakeSeed(seed?)</code> sets (or rolls and returns) a seed, <code>useFakeSetDefaultRefDate()</code> pins relative dates, and <code>useFakeList(factory, count)</code> passes the index for relations. <code>@faker-js/faker</code> is an <strong>optional peer dependency</strong> loaded through dynamic <code>import()</code>, so it never enters the initial bundle.</li></ul><h2 id="_5-1-0-2026-09-24" tabindex="-1">[5.1.0] - 2026-09-24 <a class="header-anchor" href="#_5-1-0-2026-09-24" aria-label="Permalink to &quot;[5.1.0] - 2026-09-24&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>SmartVideo media service</strong> (<code>useParseMediaSource</code>, <code>useBuildVideoEmbed</code>, <code>useGetYoutubeVideoId</code>, nocookie embed + thumbnail builders) — one <code>src</code> renders native <code>&lt;video&gt;</code> for direct files or a click-to-play facade <code>&lt;figure&gt;</code> for YouTube/Vimeo, plus <code>useEnhanceVideoFacades</code> hydration in infrastructure.</li><li><strong>YouTube channel service</strong> (<code>useInitYoutube</code>, <code>useGetChannelVideos</code>, <code>useGetVideoDetails</code>, <code>useGetUploadsPlaylistId</code>) — quota-cheap listing via <code>channels</code> → <code>playlistItems</code> (never <code>search.list</code>), and keyless RSS fallback (<code>useGetChannelVideosRss</code>, <code>useParseYoutubeRss</code>). One GCP project serves every repo; call server/build-time and cache.</li><li><strong>Zod validation, framework-agnostic</strong> (<code>zod</code> dependency, <code>katanakit-js/schemas</code> subpath) — runtime schemas for media, YouTube, RSS, AI wire shapes and common unions/errors; <code>src/types/</code> now infers via <code>z.infer</code> so consumer imports don&#39;t change. New <code>useValidate()</code> returns a Safe Result instead of throwing, and the YouTube service validates every API response at the boundary (malformed payloads → typed <code>502</code>, not garbage data).</li><li><strong>Zod coverage across the whole library</strong> — schemas now also cover core data shapes (geometry, viewport, currency, dates, agent/assistant payloads), access control (roles, capabilities, subjects) and both REST adapters. Every inferable data type in <code>src/types/</code> is now derived from a schema; contracts with methods, generics and callbacks intentionally stay as interfaces.</li><li><strong>WordPress and Notion runtime validation</strong> — responses are validated with loose schemas (extra keys like <code>_links</code>/<code>_embedded</code> are preserved), inputs are validated before any network call (<code>400</code>), malformed payloads return a typed <code>502</code> with per-field <code>details</code>, and update payloads support WP partial responses via response variants.</li><li><strong>InsForge adapter</strong> (<code>katanakit-js/adapters/insforge</code>, optional <code>@insforge/sdk</code> peer) — database fallback with <code>useIfSelect</code>/<code>useIfInsert</code>/<code>useIfUpdate</code>/<code>useIfDelete</code>/<code>useIfRpc</code>, storage (<code>useIfUpload</code>, <code>useIfDownload</code>, <code>useIfRemove</code>, <code>useIfListObjects</code>, <code>useIfGetPublicUrl</code>) and edge functions (<code>useIfInvokeFunction</code>). Mass writes are refused (update/delete require non-empty filters), inputs are Zod-validated, and the whole surface returns Safe Results.</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>WordPress <code>WpEmbedded[&quot;wp:featuredmedia&quot;]</code></strong> is now a loose partial shape instead of <code>WpMedia[]</code> (embedded media never nests <code>_embedded</code>); this breaks the runtime Zod schema cycle while keeping <code>source_url</code>/<code>id</code>/<code>title</code> typed.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>SEO <code>SiteConfig</code> errors name the missing field</strong> — <code>useSeoTag</code>, <code>useGenerateMetaTags</code>, <code>useHeadTags</code>, <code>useRssHeadLink</code> and <code>useSeoMeta</code> defaults now throw <code>[Seo] SiteConfig.seo is required</code> / <code>[Seo] SiteConfig.rss is required</code> (with the caller name) instead of <code>Cannot read properties of undefined (reading &#39;noindex&#39;)</code>. <code>nav</code> stays optional.</li></ul><h2 id="_5-0-1-2026-09-22" tabindex="-1">[5.0.1] - 2026-09-22 <a class="header-anchor" href="#_5-0-1-2026-09-22" aria-label="Permalink to &quot;[5.0.1] - 2026-09-22&quot;">​</a></h2><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Docs build maintenance</strong> — dependency/build update in the docs workspace; published to npm as 5.0.1.</li></ul><h2 id="_5-0-0-2026-09-22" tabindex="-1">[5.0.0] - 2026-09-22 <a class="header-anchor" href="#_5-0-0-2026-09-22" aria-label="Permalink to &quot;[5.0.0] - 2026-09-22&quot;">​</a></h2><p>Version alignment release (GitHub tag only; superseded by 5.0.1).</p><h2 id="_4-0-4-2026-09-22" tabindex="-1">[4.0.4] - 2026-09-22 <a class="header-anchor" href="#_4-0-4-2026-09-22" aria-label="Permalink to &quot;[4.0.4] - 2026-09-22&quot;">​</a></h2><p>Version-only release. No functional changes vs 4.0.3.</p><h2 id="_4-0-3" tabindex="-1">[4.0.3] <a class="header-anchor" href="#_4-0-3" aria-label="Permalink to &quot;[4.0.3]&quot;">​</a></h2><h3 id="changed-3" tabindex="-1">Changed <a class="header-anchor" href="#changed-3" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Query layer now runs on TanStack Query Core</strong> — <code>@tanstack/query-core</code> ships as a dependency (no separate install). The full engine is re-exported from <code>katanakit-js</code> (<code>QueryClient</code>, <code>QueryObserver</code>, <code>MutationObserver</code>, <code>focusManager</code>, <code>onlineManager</code>, <code>dehydrate</code>/<code>hydrate</code>, <code>keepPreviousData</code>, and every type), and the framework adapters (<code>useQuery</code>/<code>useMutation</code> for React, Vue, Solid, Svelte and Angular) are now thin bindings over it, returning TanStack&#39;s native result object — <code>isPending</code>, <code>isFetching</code>, <code>isSuccess</code>, <code>isError</code>, <code>data</code>, <code>error</code>, <code>status</code>, <code>fetchStatus</code>, <code>refetch</code>, <code>mutate</code>, <code>reset</code>. This replaces the hand-rolled <code>QueryClient</code>/<code>QueryCache</code>, which had correctness gaps (no-op <code>invalidateQueries</code>, blocking refetch instead of stale-while-revalidate, dead <code>refetchOnWindowFocus</code>/<code>refetchOnReconnect</code>, incomplete cancellation) and lacked infinite queries, optimistic updates, SSR hydration and devtools.</li></ul><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Framework-free query adapter</strong> (<code>katanakit-js/adapters/vanilla</code>) — pure TypeScript with no framework. Returns the raw <code>QueryObserver</code> / <code>MutationObserver</code> so you own the subscribe/render loop (DOM, canvas, CLI, worker). The framework adapters are the same plus a reactivity bridge.</li><li><strong>Query examples</strong> — <code>examples/query/</code> ships a runnable vanilla walkthrough (<code>bun run examples/query/vanilla.ts</code>) plus React, Vue, Solid, Svelte and Angular demos, and a README explaining every helper (<code>useQuery</code>, <code>useMutation</code>, <code>useSafeQueryFn</code>, <code>useQueryClient</code>, <code>useInitQueryClient</code>, <code>useCreateQueryClient</code>).</li><li>Every adapter subpath now also re-exports the client helpers (<code>useQueryClient</code>, <code>useInitQueryClient</code>, <code>useCreateQueryClient</code>, <code>useSafeQueryFn</code>), so each framework is a complete, independent entry point.</li><li><strong><code>useSafeQueryFn</code> helper</strong> — bridges KatanaKit&#39;s Safe Result (<code>useGetApi</code>/<code>useFetch</code>) into TanStack&#39;s throw-on-error <code>queryFn</code>. It receives TanStack&#39;s <code>QueryFunctionContext</code>, so <code>signal</code> can be forwarded for real request cancellation.</li><li><strong><code>useCreateQueryClient</code> helper</strong> — creates a fresh <code>QueryClient</code> per call. Use it on the server (SSR) to keep one cache per request instead of the module-level singleton (<code>useQueryClient()</code> stays the browser default).</li></ul><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li><code>useSafeQueryFn</code> now throws a real <code>Error</code> carrying only <code>message</code> + <code>status</code>; the upstream response body (<code>ApiError.details</code>) is no longer attached to the error or persisted in the query cache.</li><li><code>useInitQueryClient</code> clears the previous client&#39;s caches before swapping the singleton.</li><li><code>@tanstack/query-core</code> is pinned to an exact version.</li></ul><h2 id="_4-0-2-2026-09-22" tabindex="-1">[4.0.2] - 2026-09-22 <a class="header-anchor" href="#_4-0-2-2026-09-22" aria-label="Permalink to &quot;[4.0.2] - 2026-09-22&quot;">​</a></h2><p>Version-only re-release. No functional changes vs 4.0.1.</p><h2 id="_4-0-1" tabindex="-1">[4.0.1] <a class="header-anchor" href="#_4-0-1" aria-label="Permalink to &quot;[4.0.1]&quot;">​</a></h2><h3 id="added-4" tabindex="-1">Added <a class="header-anchor" href="#added-4" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Bun server adapter</strong> (<code>katanakit-js/adapters/bun</code>) — a Bun-native alternative to Express built on <code>Bun.serve</code> with the <code>routes</code> API (Bun v1.2.3+). Ships a dummyjson.com demo: typed route table (<code>useBuildDummyJsonRoutes</code>), HTTP handlers over the core <code>useFetch</code> (<code>useDummyJsonProducts</code>, <code>useDummyJsonProductById</code>, <code>useDummyJsonProductSearch</code>, <code>useDummyJsonUsers</code>, <code>useDummyJsonPosts</code>, <code>useDummyJsonRandomQuote</code>, …), offline seed data (<code>useGetDummyJsonSeed</code>), and a singleton server facade (<code>useBunCreate</code>/<code>useBunStart</code>/<code>useBunGetServer</code>/<code>useBunStop</code>). Run locally with <code>bun run bun:dev</code>.</li></ul><h3 id="breaking" tabindex="-1">Breaking <a class="header-anchor" href="#breaking" aria-label="Permalink to &quot;Breaking&quot;">​</a></h3><ul><li><strong>Logger API simplified</strong> — <code>useLogger</code> now takes <code>(message, data?, level?)</code> with levels reduced to <code>log | warn | error</code> (removed <code>info</code>/<code>debug</code>). The Strategy abstraction (<code>LogStrategy</code>, <code>ConsoleStrategy</code>, <code>useSetLogLevel</code>, <code>useSetStrategy</code>) and <code>useLog</code> were removed; logging maps directly onto the native <code>console</code>.</li></ul><h3 id="changed-4" tabindex="-1">Changed <a class="header-anchor" href="#changed-4" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Renamed <code>docs/</code> → <code>guides/</code></strong> — the Docusaurus site is now the <code>guides</code> workspace (<code>katanakit-guides</code>); deployment paths, scripts, <code>sync-docs-releases.mjs</code> and the Docusaurus config (<code>path: &quot;content&quot;</code>, TypeDoc <code>out</code>) were updated.</li><li><strong>Prettier + ESLint as lint/format</strong> — added <code>.vscode/settings.json</code> + <code>extensions.json</code> (Prettier default formatter, Biome disabled), formatted the whole codebase, removed stale <code>biome-ignore</code> comments and the redundant <code>eslint-config-prettier</code>.</li><li><strong>Reduced <code>package.json</code> scripts</strong> — removed broken/redundant scripts (<code>bump:all</code>, <code>assistant:demo</code>, <code>api:demo</code>, <code>notes</code>, <code>dev:adapters</code>) and dropped husky/lint-staged (the pre-commit hook could not find <code>.git</code> in the monorepo).</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong><code>invalidateQueries</code> prefix matching</strong> — now matches query keys by array prefix instead of serialized string, so invalidating <code>[&quot;users&quot;]</code> correctly invalidates <code>[&quot;users&quot;, 1]</code>.</li><li><strong>XSS hardening in <code>useSetAttribute</code></strong> — <code>srcdoc</code> is now rejected outright (a regex cannot safely sanitize entity-encoded HTML); <code>data:</code> URIs are restricted to raster images (<code>png|jpg|gif|webp</code>).</li><li><strong>Pagination caps</strong> — <code>useWpListAllPosts</code>, <code>useNotionListAllBlockChildren</code> and <code>useNotionListAllDatabasePages</code> now default to <code>maxItems = 1000</code>.</li><li><strong>Express <code>app</code> export is now lazy</strong> — importing <code>katanakit-js/adapters/express</code> no longer builds the app as a side effect.</li><li><strong>Restored CI + release workflows</strong> — <code>.github/workflows/ci.yml</code> and <code>release.yml</code> (OIDC trusted publishing) were recreated.</li><li><strong>Removed dead code</strong> — the broken <code>ErrorService</code> singleton and the Astro re-export from the main barrel.</li></ul><h2 id="_4-0-0-2026-09-20" tabindex="-1">[4.0.0] - 2026-09-20 <a class="header-anchor" href="#_4-0-0-2026-09-20" aria-label="Permalink to &quot;[4.0.0] - 2026-09-20&quot;">​</a></h2><h3 id="added-5" tabindex="-1">Added <a class="header-anchor" href="#added-5" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Framework adapters for React, Solid, Svelte and Angular</strong> — new optional subpaths (<code>katanakit-js/adapters/react</code>, <code>katanakit-js/adapters/solid</code>, <code>katanakit-js/adapters/svelte</code>, <code>katanakit-js/adapters/angular</code>) exposing <code>useQuery</code>, <code>useMutation</code>, <code>useRequest</code>, and <code>useWatch</code> over the core <code>QueryClient</code> and HTTP layer, each with the framework&#39;s native reactivity: React hooks (<code>useState</code>/<code>useEffect</code>), Solid signals, Svelte readable stores, and Angular signals (injection-context aware via <code>DestroyRef</code>). All adapters share the global query cache, so data is shared across frameworks.</li><li><strong><code>useRequest</code> renamed from <code>useKatanaFetch</code></strong> — the Vue reactive-fetch composable is now <code>useRequest</code> for brevity and consistency across adapters. <code>useKatanaFetch</code> remains as a deprecated alias.</li><li><strong>Interactive playground</strong> — Vue 3 + Vite dev environment (<code>playground/</code>) for testing library features in-browser. Run with <code>pnpm playground:dev</code>. Includes demos for <code>useRequest</code>, <code>useQuery</code>, <code>useWatch</code>, and <code>useBuildUrl</code> with real API calls (PokeAPI, JSONPlaceholder).</li><li><strong>Notion REST API adapter</strong> (<code>katanakit-js/adapters/notion</code>) — typed client for the Notion API with <code>useInitNotion</code> for token registration. Covers Pages (get, create, update, archive), Blocks (get, get children, append, update, delete), Databases (get schema, query, create, update), Users (get, list), and Search. Includes auto-pagination helpers: <code>useNotionListAllBlockChildren</code> and <code>useNotionListAllDatabasePages</code> that handle cursor-based pagination automatically. All functions return <code>FetchResult&lt;T&gt;</code> (safe result pattern).</li><li><strong>WordPress REST API adapter</strong> (<code>katanakit-js/adapters/wordpress</code>) — typed client for the WordPress REST API with <code>useInitWordPress</code> supporting Application Passwords, JWT, Basic Auth, and nonce-based authentication. Covers Posts, Pages, Media (with file upload via <code>useWpUploadMedia</code>), Categories, Tags, Comments, Users, and Custom Post Types with full CRUD operations. Includes batch operations (<code>useWpBatch</code>), auto-pagination (<code>useWpListAllPosts</code>), search (<code>useWpSearchAllPosts</code>), and slug-based routing (<code>useWpFindPostBySlug</code>). All functions return <code>FetchResult&lt;T&gt;</code>.</li><li><strong>WordPress <code>_fields</code> support</strong> — new <code>WpQueryParams._fields</code> parameter to limit response fields, reducing payload by 60-80% for list views. Supports nested field selection: <code>&quot;id,title,link&quot;</code> or <code>&quot;id,title.rendered,acf.hero_image&quot;</code>.</li><li><strong>WordPress <code>_embed</code> as string</strong> — <code>WpQueryParams._embed</code> now accepts <code>boolean | string</code> for selective resource embedding: <code>&quot;_embed: author,wp:featuredmedia&quot;</code> embeds only author and featured media. Typed <code>WpEmbedded</code> interface for <code>_embedded</code> responses with proper <code>author[]</code>, <code>wp:featuredmedia[]</code>, <code>wp:term[][]</code>, and <code>replies[][]</code> types.</li><li><strong>WordPress ACF (Advanced Custom Fields) support</strong> — <code>WpAcfFields</code> type for ACF field data on posts, pages, media, taxonomies, users, and options. ACF fields are accessible via <code>post.acf?.field_name</code> when using <code>_fields: &quot;id,acf&quot;</code>.</li><li><strong>WordPress <code>media_details</code> complete types</strong> — added <code>filesize</code>, <code>image_meta</code> (EXIF data), and complete <code>sizes</code> structure with <code>file</code>, <code>mime_type</code>, and <code>filesize</code> per size.</li><li><strong>Vue and Nuxt framework examples</strong> — SFC examples for blog listings and dynamic <code>[slug]</code> routes using <code>useQuery</code> (Vue) and <code>useAsyncData</code> (Nuxt) with SSR support.</li><li><strong>Framework examples</strong> — Astro and Next.js (React) demos for both adapters showing real-world usage: blog listings, dynamic <code>[slug]</code> routes, database queries, block rendering, media uploads, and taxonomy management. Examples live in <code>examples/notion/</code> and <code>examples/wordpress/</code>.</li></ul><h3 id="changed-5" tabindex="-1">Changed <a class="header-anchor" href="#changed-5" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>npm v12 security hardening</strong> — added <code>.npmrc</code> with <code>allow-scripts=</code> to block dependency lifecycle scripts (npm v12 default). Added <code>.github/workflows/release.yml</code> with OIDC trusted publishing for automated releases without long-lived NPM_TOKEN. Updated AGENTS.md with new release workflow and security notes.</li><li><strong>Improved documentation</strong> — expanded <code>useBuildUrl</code> section with real-world use cases (navigation links, image URLs, third-party libraries, debugging, SSR), updated <code>CONTRIBUTING.md</code> to reflect current tooling (pnpm), added contribution invitation to README.</li><li><strong>Kitt AI assistant documentation</strong> — added &quot;When to use Kitt&quot; and &quot;When to use alternatives&quot; comparison table with links to Vercel AI SDK, LangChain, CrewAI, and Botpress.</li></ul><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Query cache</strong> — <code>fetchQuery</code> no longer reuses the placeholder <code>queryFn</code> from <code>subscribe()</code> (which returned empty data); the error state is no longer corrupted to <code>[object Object]</code>; <code>cancelQueries</code> now actually cancels.</li><li><strong>SSRF</strong> — <code>useFetch</code> fails closed on redirects (<code>redirect: &quot;error&quot;</code>).</li><li><strong>DOM sanitizer</strong> — blocks <code>data:</code>, <code>vbscript:</code> and control-character scheme bypasses.</li><li><strong>Prisma subpath</strong> — importing <code>katanakit-js/prisma</code> no longer throws without <code>DATABASE_URL</code> (lazy client).</li><li><strong>Notion/WordPress</strong> — return Safe Results when unconfigured; WordPress nonce auth now sends the cookie.</li><li><strong>SSR guards</strong> — <code>useCopyToClipboard</code> and storage access are now SSR-safe.</li></ul><h2 id="_3-1-0-2026-09-14" tabindex="-1">[3.1.0] - 2026-09-14 <a class="header-anchor" href="#_3-1-0-2026-09-14" aria-label="Permalink to &quot;[3.1.0] - 2026-09-14&quot;">​</a></h2><h3 id="added-6" tabindex="-1">Added <a class="header-anchor" href="#added-6" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Generic <code>useKatanaWatch</code> / <code>useWatch</code> composables</strong> — watcher in <code>katanakit-js/adapters/vue</code> (re-exported from <code>katanakit-js/adapters/nuxt</code>) wrapping the native Vue <code>watch</code> with <code>deep: true</code> by default. Props (<code>WatchSource</code>, <code>WatchCallback</code>, <code>WatchOptions</code>, <code>WatchStopHandle</code>) are taken from the native <code>watch</code> and live in <code>src/types/</code>; the callback accepts any internal function (sync/async, with or without args). Accepts a ref, reactive object, getter function or array of sources, stops automatically on unmount, and powers use cases like revalidating a form (<code>safeParse</code> with Zod, Valibot, Standard Schema or custom validators) on every nested change. Schema-agnostic types (<code>FieldErrors</code>, <code>ValidationSchema</code>) also live in <code>src/types/</code>.</li></ul><h2 id="_3-0-1-2026-09-13" tabindex="-1">[3.0.1] - 2026-09-13 <a class="header-anchor" href="#_3-0-1-2026-09-13" aria-label="Permalink to &quot;[3.0.1] - 2026-09-13&quot;">​</a></h2><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong><code>express-rate-limit</code> was imported by the assistant adapter but never declared</strong> — the published package crashed with <code>ERR_MODULE_NOT_FOUND</code> for consumers of <code>katanakit-js/adapters/assistant</code>. It is now a runtime dependency (<code>8.7.0</code>, which ships its own types); the deprecated <code>@types/express-rate-limit</code> stub was removed.</li><li><strong>Prisma client was initialized eagerly on import</strong> — <code>src/prisma/use-prisma.ts</code> exported a module-level <code>prisma</code> instance that threw on import when <code>DATABASE_URL</code> was missing, breaking any app that imported <code>katanakit-js/prisma</code> and making the documented <code>usePrismaClient(url)</code> override unusable. The eager export was removed (it was not re-exported from any barrel, so this is non-breaking).</li><li><strong>Release cards never badged <code>major</code></strong> — the version regex in <code>scripts/sync-docs-releases.mjs</code> was double-escaped, so <code>x.0.0</code> releases rendered as <code>Minor release</code>. Fixed and regenerated.</li></ul><h3 id="changed-6" tabindex="-1">Changed <a class="header-anchor" href="#changed-6" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Migrated the repository from Yarn 4 to pnpm 12</strong> — <code>packageManager</code> pinned to <code>pnpm@12.4.1</code>, <code>pnpm-lock.yaml</code> replaces <code>yarn.lock</code>, workspace declared in <code>pnpm-workspace.yaml</code> (replacing the <code>workspaces</code> field), Yarn <code>resolutions</code> moved to pnpm <code>overrides</code>, CI uses <code>pnpm/action-setup</code> + <code>pnpm install --frozen-lockfile</code>, Husky pre-commit runs <code>pnpm lint-staged</code>, and all docs/config/scripts references updated. Release bumping now goes through <code>scripts/bump-version.mjs</code> (pnpm&#39;s <code>version</code> refuses a dirty working tree).</li><li><strong><code>.gitignore</code> now ignores all <code>.env*</code> variants</strong> (previously only the exact <code>.env</code>), with <code>.env.example</code> still tracked.</li></ul><h2 id="_3-0-0-2026-09-13" tabindex="-1">[3.0.0] - 2026-09-13 <a class="header-anchor" href="#_3-0-0-2026-09-13" aria-label="Permalink to &quot;[3.0.0] - 2026-09-13&quot;">​</a></h2><h3 id="breaking-1" tabindex="-1">Breaking <a class="header-anchor" href="#breaking-1" aria-label="Permalink to &quot;Breaking&quot;">​</a></h3><ul><li><strong>Prisma model <code>User</code> renamed to <code>Account</code></strong> (<code>@@map(&quot;accounts&quot;)</code>); <code>Post.author</code> now points to <code>Account</code>. Consumers of <code>katanakit-js/prisma</code> must switch <code>db.public.User</code> to <code>db.public.Account</code>. Table rename <code>users</code> → <code>accounts</code> requires a migration on live databases.</li></ul><h3 id="added-7" tabindex="-1">Added <a class="header-anchor" href="#added-7" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Access-control service</strong> — pure role/capability registry in <code>src/core/services/access.service.ts</code> with hierarchy-based inheritance: <code>owner</code> &gt; <code>admin</code> &gt; <code>editor</code> &gt; <code>author</code> &gt; <code>member</code> &gt; <code>guest</code>. Exposes <code>useCan</code>, <code>useHasRole</code>, <code>useCapabilitiesFor</code>, <code>useRegisterRole</code>, <code>useRoles</code> and <code>useResetRoles</code>. Types (<code>AccessRole</code>, <code>AccessCapability</code>, <code>AccessRoleDefinition</code>, <code>AccessSubject</code>, <code>IAccessService</code>) live in <code>src/types/</code>.</li><li><strong>Express access guard</strong> — <code>useRequireCapability(capability, resolveSubject)</code> in <code>katanakit-js/adapters/express</code> builds a <code>RequestHandler</code> that returns 401 for anonymous requests and 403 when the capability is missing. Plugs into the existing <code>guard</code> seam of the assistant router; unwired by default.</li></ul><h3 id="changed-7" tabindex="-1">Changed <a class="header-anchor" href="#changed-7" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Docs releases automated</strong> — <code>scripts/sync-docs-releases.mjs</code> generates the homepage release cards, the docs changelog and the navbar Releases dropdown from git tags + Conventional Commits. <code>yarn docs:build</code> syncs first; CI runs <code>yarn docs:check</code> and fails on drift. The navbar now lists the latest 8 release tags with direct links to GitHub.</li><li><strong>Merge-into-dev-first workflow</strong> — feature branches must be merged into <code>dev</code> (<code>git checkout dev &amp;&amp; git merge &lt;branch&gt;</code>) before any PR; PRs to <code>main</code> come only from <code>dev</code>. Documented in <code>AGENTS.md</code>.</li></ul><h2 id="_2-15-0-2026-09-13" tabindex="-1">[2.15.0] - 2026-09-13 <a class="header-anchor" href="#_2-15-0-2026-09-13" aria-label="Permalink to &quot;[2.15.0] - 2026-09-13&quot;">​</a></h2><h3 id="added-8" tabindex="-1">Added <a class="header-anchor" href="#added-8" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>QueryClient</strong> — <code>QueryClient</code> + <code>QueryCache</code> built on the reactive kernel. Features: cache with GC, query keys, stale-while-revalidate, retry with exponential backoff, deduplication, invalidation, refetch-on-window-focus, and <code>prefetchQuery</code>. Integrates with the existing API manager (<code>useFetch</code>, <code>useGetApi</code>) and Safe Results pattern.</li><li><strong>Vue <code>useQuery</code> / <code>useMutation</code> composables</strong> — reactive composables in <code>katanakit-js/adapters/vue</code> that wrap the QueryClient with Vue 3 reactivity (<code>data</code>, <code>error</code>, <code>isLoading</code>, <code>status</code>, <code>refetch</code>, <code>mutate</code>).</li><li><strong>Husky + lint-staged pre-commit hook</strong> — runs <code>eslint --fix</code> on staged <code>src/**/*.ts</code> files before every commit (installed via <code>yarn install</code>). Prevents lint failures from reaching CI.</li><li><strong><code>AGENTS.md</code></strong> — compact instruction file for AI agents (commands, architecture, git/CI workflow, Prisma skills).</li></ul><h3 id="added-tests" tabindex="-1">Added (Tests) <a class="header-anchor" href="#added-tests" aria-label="Permalink to &quot;Added (Tests)&quot;">​</a></h3><ul><li>13 new tests for QueryClient (<code>tests/query.service.test.ts</code>) — 127 tests total.</li></ul><h3 id="changed-8" tabindex="-1">Changed <a class="header-anchor" href="#changed-8" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Replaced Biome with ESLint + Prettier</strong> — migrated linting and formatting from Biome 2.5.12 (Rust, 38ms) to ESLint 10 + Prettier 3.9 (JS, ~4.3s). Same rules enforced: tabs, double quotes, semicolons, trailing commas, import sorting (<code>eslint-plugin-simple-import-sort</code>), recommended lint rules. TypeScript 7.0 has no compiler API; aliased <code>typescript</code> to <code>@typescript/typescript6@6.0.2</code> for type-aware linting. <code>tsc6</code> replaces <code>tsc</code> for type checking.</li><li><strong>CI matrix <code>fail-fast: false</code></strong> — the Node 22/24 jobs now run to completion even if one version fails, so a failure on one version no longer cancels the other.</li></ul><h2 id="_2-14-2-2026-09-13" tabindex="-1">[2.14.2] - 2026-09-13 <a class="header-anchor" href="#_2-14-2-2026-09-13" aria-label="Permalink to &quot;[2.14.2] - 2026-09-13&quot;">​</a></h2><h3 id="added-9" tabindex="-1">Added <a class="header-anchor" href="#added-9" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Katana UI documentation</strong> — new docs section describing the planned framework-agnostic UI kit: vision, layered architecture, full inventory (dashboards, e-commerce, apps, auth, blocks, layouts, interactions, charts and themes), LLM files strategy and delivery roadmap.</li><li><strong>Navbar theme switch</strong> — the docs site replaces the default color mode button with a checkbox switch (swizzled <code>ColorModeToggle</code>) with keyboard focus, reduced-motion support and pre-hydration styling.</li></ul><h3 id="changed-9" tabindex="-1">Changed <a class="header-anchor" href="#changed-9" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Docs sidebar includes a UI Kit category, and the toolkit roadmap links to it.</li></ul><h2 id="_2-14-1-2026-09-10" tabindex="-1">[2.14.1] - 2026-09-10 <a class="header-anchor" href="#_2-14-1-2026-09-10" aria-label="Permalink to &quot;[2.14.1] - 2026-09-10&quot;">​</a></h2><h3 id="changed-10" tabindex="-1">Changed <a class="header-anchor" href="#changed-10" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Pinned all dependency versions</strong> to exact (removed <code>^</code>/<code>~</code> ranges) for deterministic installs and supply chain safety.</li><li>Added <code>resolutions</code> for transitive floating deps: <code>pathe@2.0.3</code>, <code>jsbi@4.3.2</code>.</li></ul><h3 id="removed" tabindex="-1">Removed <a class="header-anchor" href="#removed" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li>Removed unused <code>@types/bun</code> dev dependency.</li></ul><h3 id="added-10" tabindex="-1">Added <a class="header-anchor" href="#added-10" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li>Added <code>socket.yml</code> for Socket.dev supply chain security configuration.</li></ul><h2 id="_2-14-0-2026-09-10" tabindex="-1">[2.14.0] - 2026-09-10 <a class="header-anchor" href="#_2-14-0-2026-09-10" aria-label="Permalink to &quot;[2.14.0] - 2026-09-10&quot;">​</a></h2><h3 id="added-11" tabindex="-1">Added <a class="header-anchor" href="#added-11" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Kitt AI agent system</strong> — OpenAI-compatible provider with tool-calling loop, session management, and conversation store. Built on a generic <code>AgentService</code> that handles system prompts, tool registration, and iterative LLM interaction until task completion.</li><li><strong>REST assistant adapter</strong> (<code>katanakit-js/adapters/assistant</code>) — <code>POST /chat</code> for sending messages, <code>GET /sessions</code> for listing conversations, <code>DELETE /sessions/:id</code> for cleanup. Includes auth guard, per-session context, and conversation persistence.</li><li><strong>Telegram adapter</strong> (<code>katanakit-js/adapters/telegram</code>) — long-polling bot via <code>getUpdates</code>, <code>sendMessage</code> reply with Markdown formatting, BotFather integration guide. Configurable polling interval and error handling.</li><li><strong>WhatsApp adapter</strong> (<code>katanakit-js/adapters/whatsapp</code>) — Meta Cloud API webhook receiver, HMAC signature verification (<code>X-Hub-Signature-256</code>), rate limiting (60 req/min), and async message processing with <code>messages.update</code> / <code>messages.received</code> event types.</li><li><strong>Prisma conversation store</strong> — <code>Conversation</code> + <code>Message</code> models in <code>prisma/schema.prisma</code> with session tracking, timestamps, and message history. New <code>assistant.store.ts</code> service for create/list/get/delete operations.</li><li><strong>GitHub Actions CI</strong> — <code>.github/workflows/ci.yml</code> runs lint, typecheck, build, and 114 tests on Node 22 and 24.</li><li><strong>Rate limiting</strong> — <code>express-rate-limit</code> on assistant routes (20 req/min) and WhatsApp webhook (60 req/min) with standard rate-limit headers.</li><li><strong><code>examples/assistant/</code></strong> — full demo with knowledge base, system prompt, and session management.</li><li><strong><code>examples/agent/</code></strong> — agent demo showing tool-calling loop with multiple registered tools.</li><li>New test suites: <code>agent.service.test.ts</code>, <code>assistant.service.test.ts</code>, <code>telegram.service.test.ts</code>, <code>whatsapp.service.test.ts</code>, <code>express.server.test.ts</code> — 114 tests total.</li></ul><h3 id="changed-11" tabindex="-1">Changed <a class="header-anchor" href="#changed-11" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>Express server restructured</strong> — idempotent <code>create()</code>/<code>finalize()</code> pattern prevents double-initialization; <code>rawBody</code> capture via <code>verify</code> callback for signature verification; route ordering fix so static paths match before parameterized routes.</li><li><strong>Type definitions expanded</strong> — new agent, assistant, and adapter types in <code>src/types/index.ts</code> covering <code>AgentConfig</code>, <code>ToolDefinition</code>, <code>SessionMessage</code>, <code>AssistantConfig</code>, <code>TelegramConfig</code>, <code>WhatsAppConfig</code>, and webhook event types.</li><li><strong>Prisma schema updated</strong> — new <code>Conversation</code> and <code>Message</code> models; schema types regenerated.</li></ul><h3 id="fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-4" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Timing-safe HMAC comparison</strong> — WhatsApp signature verification uses <code>crypto.timingSafeEqual</code> instead of string <code>===</code> to prevent timing attacks.</li><li><strong>HTTPS enforcement</strong> — WhatsApp webhook rejects non-HTTPS requests in production.</li><li><strong>Path confinement</strong> — file operations in storage service restricted to project root to prevent directory traversal.</li><li><strong>Per-tool error capture</strong> — agent tool failures are captured individually without crashing the entire tool-calling loop.</li><li><strong>Build output directory</strong> — <code>outDir</code> in <code>tsconfig.json</code> corrected; <code>yarn clean</code> ensures clean builds before each release.</li></ul><h2 id="_2-0-0-2026-09-03" tabindex="-1">[2.0.0] - 2026-09-03 <a class="header-anchor" href="#_2-0-0-2026-09-03" aria-label="Permalink to &quot;[2.0.0] - 2026-09-03&quot;">​</a></h2><p>Developed and published as <code>katanakit-dev</code>.</p><h3 id="added-12" tabindex="-1">Added <a class="header-anchor" href="#added-12" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Reorganized the project</strong> with hexagonal architecture into <code>types/</code>, <code>core/services/</code>, <code>infrastructure/</code>, <code>adapters/</code>, <code>config/</code>, and <code>prisma/</code>.</li><li>Exposed the public API through barrel files (<code>src/index.ts</code> and per-layer <code>index.ts</code>).</li><li>Added Vitest unit tests for the HTTP client, logger, storage, DOM, and reactive services.</li><li>Added English documentation (<code>README.md</code>, <code>CONTRIBUTING.md</code>, <code>docs/</code>, <code>SECURITY.md</code>).</li></ul><h3 id="fixed-5" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-5" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Fixed TypeScript compile errors: broken imports, broken singleton guards (<code>TimingService</code> and <code>ViewportService</code>), the <code>FIND_ENTRY</code> scope bug in <code>AstroService</code>, and Express <code>Request</code>/<code>Response</code> typing.</li><li>Removed all side effects on import (top-level <code>fetch</code> to dummyjson.com, <code>console.log</code> calls, storage writes and timers).</li><li>Fixed the Express server: <code>listen</code> now uses the configured port/host, the user router is mounted, and handler <code>(req, res)</code> argument order is correct.</li><li>Fixed the logger call sites (level is now the first argument of <code>useLog</code>).</li></ul><h3 id="removed-1" tabindex="-1">Removed <a class="header-anchor" href="#removed-1" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li>Removed duplicate type definitions (unified in <code>src/types/</code>).</li><li>Dead code, empty files and the broken signals draft.</li><li>Moved demos to <code>examples/</code> and dropped the obsolete <code>wiki/</code> documentation.</li></ul><h2 id="_1-x-earlier" tabindex="-1">[1.x] - Earlier <a class="header-anchor" href="#_1-x-earlier" aria-label="Permalink to &quot;[1.x] - Earlier&quot;">​</a></h2><p>Initial release series focusing on core KatanaKit functionality and framework adapters.</p><h2 id="_0-1-0-initial-release" tabindex="-1">[0.1.0] - Initial release <a class="header-anchor" href="#_0-1-0-initial-release" aria-label="Permalink to &quot;[0.1.0] - Initial release&quot;">​</a></h2><p>First public release of KatanaKit.</p><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>MIT</p>',104)])])}const p=o(s,[["render",c]]);export{g as __pageData,p as default};
